-- 0027: experiencias de programas. Cada programa Premium cambia la app entera mientras dura:
-- ejercicios enfocados en su objetivo, hábitos diarios (daily_logs.program_checks), consejo semanal de Coach Banana,
-- comida del programa y su portada. Programas nuevos: Abdomen marcado, Brazos definidos y Banana Girl.
-- Glúteos de acero se rehace como especialización completa de glúteo (mismo slug: las compras siguen valiendo).
-- Requiere 0024. Idempotente: se puede correr más de una vez.

-- ───────────── 1. Hábitos que la persona marca a mano ─────────────
alter table public.daily_logs add column if not exists program_checks text[] not null default '{}';
do $$ begin
  alter table public.daily_logs drop constraint if exists daily_logs_program_checks_check;
  alter table public.daily_logs add constraint daily_logs_program_checks_check check (
    cardinality(program_checks) <= 8 and array_to_string(program_checks, ',') ~ '^[a-z0-9,-]*$'
  );
end $$;

-- ───────────── 2. Portada "fresa" (Banana Girl) ─────────────
do $$ begin
  alter table public.challenges_catalog drop constraint if exists challenges_catalog_store_check;
  alter table public.challenges_catalog add constraint challenges_catalog_store_check check (
    status in ('borrador','publicado','oculto','archivado')
    and price_usd >= 0 and price_usd <= 200 and (price_usd = 0 or price_usd >= 0.5)
    and difficulty in ('facil','media','dificil')
    and minutes between 1 and 240
    and cover in ('banana','ember','sky','peel','noche','selva','fresa')
    and (verify is null or verify in ('manual','workout','steps','protein','water'))
    and (grace is null or grace between 0 and 60)
    and (xp is null or xp between 0 and 400)
    and (steps_goal is null or steps_goal between 1000 and 50000)
    and start_mode in ('libre','fecha') and (start_mode = 'libre' or start_date is not null)
    and (onvo_price_id is null or char_length(onvo_price_id) <= 80)
    and (badge is null or char_length(badge) <= 60)
    and (reward_title is null or char_length(reward_title) <= 40)
    and (icon is null or char_length(icon) <= 24)
    and (safety_note is null or char_length(safety_note) <= 600)
  );
end $$;

-- ───────────── 3. Siembra ─────────────
-- ───────────── Siembra de programas nuevos (generada con scripts/gen-programas-seed.ts --0027) ─────────────
on conflict (slug) do nothing;
on conflict (slug) do nothing;
on conflict (slug) do nothing;
on conflict (slug, phase, day) do nothing;

-- Programas de 0024 rehechos en 0027 (enfoque completo en su objetivo). Mismo slug: las compras siguen valiendo.
update public.challenges_catalog set program = $j${"phases":[{"name":"Activación y técnica","weeks":2,"focus":"Siente el glúteo en cada repetición: pausas arriba y bajadas lentas."},{"name":"Carga progresiva","weeks":3,"focus":"Una serie más en hip thrust, sentadilla y abducción, y más peso cuando llegas al tope."},{"name":"Semana pico","weeks":1,"focus":"Tu hip thrust más pesado y la comparación con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio o casa con mancuernas y banda","adapt":true,"who":"Para quien quiere más glúteo y caderas más firmes, y puede entrenar glúteo 3 veces por semana durante 6 semanas, en el gimnasio o en casa.","result":"Construir glúteo con 3 sesiones dedicadas por semana y una exprés opcional: hip thrust, sentadilla y zancada profundas, bisagra de cadera y abducción para la parte alta.","outcomes":["Glúteo en todas las sesiones: unas 20 a 25 series semanales","Ejercicios en posición estirada (sentadilla profunda, búlgara) y en contracción (hip thrust)","Versión para casa de cada ejercicio de máquina","Fuerza en hip thrust y peso muerto rumano comparada con el día 1"],"keyLifts":["ds:1409","rdl","goblet"],"nutrition":{"mode":"fuerza","proteinPerKg":1.8,"note":"Superávit pequeño (unas 200 a 300 kcal) y proteína alta: el glúteo necesita energía para crecer."},"previewExercise":"rdl","experience":{"mode":"Modo glúteo","welcome":"Empieza Glúteos de acero. Antes de cada sesión, activa tu glúteo 5 minutos: lo vas a sentir mucho más en cada repetición.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"activacion","label":"Activación de glúteo de 5 minutos","kind":"check"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"pasos","label":"Camina 8.000 pasos","kind":"pasos","target":8000}],"tips":["Semana 1: en el puente con barra, pausa 1 segundo arriba y aprieta. Si sientes la espalda baja, mete el mentón y las costillas.","Semana 2: en el peso muerto rumano la cadera va hacia atrás, no hacia abajo. Para cuando sientas el estiramiento detrás del muslo.","Semana 3: el glúteo crece con carga. Si completas el rango, deja que el peso suba aunque te dé miedo.","Semana 4: en la búlgara, inclina un poco el torso al frente para que trabaje más el glúteo.","Semana 5: come suficiente. Un superávit pequeño y proteína alta son la energía que tu glúteo necesita para crecer.","Semana 6: semana pico. Prueba tu mejor puente con barra y compara con la semana 1."],"coachFocus":"Construir glúteo: técnica del puente con barra, bisagra de cadera y trabajo a una pierna, con superávit pequeño y proteína alta.","restDay":"Descanso activo: 10 minutos de puente de glúteo y estiramiento de cadera","food":["Come un poco más de lo que gastas: unas 250 kcal extra al día, sobre todo en carbohidratos alrededor del entreno.","Proteína en cada comida, también en el desayuno: huevos, yogur griego o queso.","Arroz, papa, plátano, avena y tortillas son tus aliados: el glúteo crece con energía.","Después de entrenar: proteína y carbohidrato en la siguiente comida."]}}$j$::jsonb, description = '6 semanas de especialización en glúteo: hip thrust, sentadilla y zancada profundas, peso muerto rumano y abducción, 3 sesiones dedicadas y 1 exprés opcional por semana. En el gimnasio o en casa.', minutes = 45, days = 42 where slug = 'gluteos-30' and kind = 'programa';
delete from public.program_sessions where slug = 'gluteos-30';
on conflict (slug, phase, day) do nothing;
-- Duración en días = semanas del programa (algunos retos convertidos en 0024 conservaban la de 0018).
update public.challenges_catalog set days = 42 where slug = 'dominadas-desde-cero' and kind = 'programa' and days <> 42;
update public.challenges_catalog set days = 21 where slug = 'abdomen-21' and kind = 'programa' and days <> 21;
update public.challenges_catalog set days = 42 where slug = 'pierde-3kg-6-semanas' and kind = 'programa' and days <> 42;
-- Experiencia de los programas de 0024: solo si el panel todavía no les puso una.
update public.challenges_catalog set program = program || jsonb_build_object('experience', $j${"mode":"Modo reconstrucción","welcome":"Empieza tu reconstrucción. Estas primeras semanas usa cargas cómodas y técnica limpia: el programa sube el peso cuando estás listo.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"pasos","label":"Camina 8.000 pasos","kind":"pasos","target":8000},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: el objetivo es aprender. Termina cada serie sintiendo que podías hacer 2 o 3 repeticiones más.","Semana 2: anota cada serie. Si completas el rango con buena técnica, el peso sube solo la próxima vez.","Semana 3: la proteína es tu ladrillo. Busca una porción del tamaño de tu mano en cada comida.","Semana 4: empieza la construcción. Más series en los básicos; descansa completo entre series pesadas.","Semana 5: si un día llegas sin energía, haz la sesión con el mismo peso. Constancia antes que heroísmo.","Semana 6: compara tus pesos con la semana 1. Ese es el músculo que estás recuperando.","Semana 7: semana ligera. Bajar la carga ahora te deja llegar fuerte al cierre.","Semana 8: cierre. Iguala o supera tus marcas y toma tus medidas el último día."],"coachFocus":"Recuperar músculo y fuerza después de bajar de peso rápido, sin recuperar la grasa. Prioriza técnica, proteína y progresión de cargas.","restDay":"Descanso activo: camina 20 minutos y estira 10","food":["Proteína en cada comida: pollo, huevo, pescado, frijoles con queso o yogur griego.","Déficit pequeño: no recortes más comida. Tu músculo necesita energía para reconstruirse.","Antes de entrenar, algo con carbohidrato: arroz, pan, fruta o avena.","Si usas GLP-1, come la proteína primero, aunque tengas poco apetito."]}$j$::jsonb) where slug = 'reconstruccion-8-semanas' and kind = 'programa' and program is not null and not (program ? 'experience');
update public.challenges_catalog set program = program || jsonb_build_object('experience', $j${"mode":"Modo dominada","welcome":"Empieza Dominadas desde cero. Cada sesión cuenta: colgarte, retraer y bajar despacio construyen la fuerza para subir.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"colgarte","label":"Cuélgate de la barra 3 veces 20 segundos","kind":"check"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: en la dominada escapular los brazos no se doblan. Solo bajas y juntas los omóplatos.","Semana 2: tu agarre también se entrena. Colgarte unos segundos extra al final de cada serie suma.","Semana 3: en las negativas, cuenta 5 segundos en la bajada. Si bajas en menos de 3, termina la serie.","Semana 4: usa la banda más delgada con la que llegues al rango. Menos ayuda, más fuerza.","Semana 5: intenta tu primera dominada estricta al empezar la sesión, cuando estás fresco.","Semana 6: semana de prueba. Anota cuántas estrictas haces y compáralo con el día 1."],"coachFocus":"Lograr la primera dominada estricta: progresión de escapulares a negativas y a intentos, agarre y espalda.","restDay":"Descanso activo: cuélgate de la barra 3 veces y camina 20 minutos","food":["Proteína en cada comida para que tu espalda se haga más fuerte.","Si quieres que la dominada salga antes, bajar un poco de grasa ayuda: menos peso que subir.","Carbohidrato antes de entrenar para tener fuerza en los intentos.","Agua durante el día: el agarre se cansa antes cuando estás deshidratado."]}$j$::jsonb) where slug = 'dominadas-desde-cero' and kind = 'programa' and program is not null and not (program ? 'experience');
update public.challenges_catalog set program = program || jsonb_build_object('experience', $j${"mode":"Modo core","welcome":"Empieza 21 días de abdomen. Sesiones cortas, core bloqueado y espalda baja protegida en cada ejercicio.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"core","label":"1 minuto de plancha extra","kind":"check"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"pasos","label":"Camina 8.000 pasos","kind":"pasos","target":8000}],"tips":["Semana 1: en la plancha, aprieta glúteos y lleva el ombligo hacia la columna. Calidad antes que segundos.","Semana 2: en los oblicuos, gira desde el torso y no desde los brazos.","Semana 3: semana pico. Que se vea el abdomen depende de tu grasa corporal: cuida tu comida y tus pasos."],"coachFocus":"Core fuerte y estable: anti-extensión, oblicuos y abdomen inferior con la espalda baja protegida.","restDay":"Descanso activo: camina 20 minutos y 2 minutos de plancha","food":["Que se vea el abdomen depende de tu grasa corporal: cuida las porciones.","Fibra en cada comida: frutas, verduras, frijoles y avena te mantienen lleno.","Cambia las bebidas azucaradas por agua o café sin azúcar.","Proteína en cada comida para cuidar tu músculo mientras bajas."]}$j$::jsonb) where slug = 'abdomen-21' and kind = 'programa' and program is not null and not (program ? 'experience');
update public.challenges_catalog set program = program || jsonb_build_object('experience', $j${"mode":"Modo quema","welcome":"Empieza Pierde 3 kg. Fuerza para cuidar tu músculo, intervalos suaves y pasos cada día: el déficit hace el resto.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"pasos","label":"Camina 10.000 pasos","kind":"pasos","target":10000},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"}],"tips":["Semana 1: pésate 3 mañanas por semana, al despertar. La app usa la tendencia, no el número de un día.","Semana 2: los pasos suman más de lo que parece. Camina 10 minutos después de cada comida.","Semana 3: si la báscula se detiene, mira tus medidas. A veces bajas cintura antes que kilos.","Semana 4: la proteína te mantiene lleno. Empieza cada comida por ella.","Semana 5: duerme 7 horas. Dormir poco sube el hambre al día siguiente.","Semana 6: última semana. Pésate y mide tu cintura el último día para comparar con el día 1."],"coachFocus":"Bajar unos 0,5 kg por semana sin perder músculo: déficit moderado, proteína alta, pasos y fuerza.","restDay":"Descanso activo: camina 30 minutos","food":["Déficit moderado: unas 500 kcal menos al día, no más.","Empieza cada comida por la proteína y las verduras.","Las bebidas con azúcar y el alcohol son lo primero que conviene recortar.","Ten listas comidas fáciles: pollo desmenuzado, huevos duros, frijoles y arroz."]}$j$::jsonb) where slug = 'pierde-3kg-6-semanas' and kind = 'programa' and program is not null and not (program ? 'experience');

-- Comprobación: los programas y su modo.
select slug, title, status, price_usd, program->'experience'->>'mode' as modo from public.challenges_catalog where kind = 'programa' order by sort;
