insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('abdomen-marcado', 'Abdomen marcado', '6 semanas para un abdomen más marcado: core en cada sesión, fuerza de cuerpo completo, un circuito de quema y el ajuste de comida y pasos que hace falta para bajar grasa.', 42, '{}'::jsonb, 'publicado', 7.99, 'media', 40, 'sky', 'target', 'workout', 0, 400, 'Abdomen marcado', 'Core de acero', 'libre', true, false, 'Si tienes diástasis abdominal, una hernia, dolor de espalda baja, estás embarazada o tuviste un parto reciente, consulta con tu médico antes de empezar.', 20, 'programa', $j${"phases":[{"name":"Base","weeks":2,"focus":"Core estable, fuerza de cuerpo completo y el hábito de 4 sesiones por semana."},{"name":"Quema","weeks":3,"focus":"Más series, más tiempo en las planchas y un intervalo más en el circuito."},{"name":"Pico","weeks":1,"focus":"Variantes más difíciles y tu medida de cintura del último día."}],"daysPerWeek":4,"sessionMinutes":40,"level":"todos","equipment":"Gimnasio o casa con mancuernas","adapt":true,"who":"Para quien quiere ver su abdomen más marcado: core fuerte, cintura más pequeña y menos grasa abdominal, sin pasar horas haciendo abdominales.","result":"Bajar grasa y fortalecer el abdomen con 2 sesiones de fuerza y core, 1 de core y cardio y 1 circuito de quema por semana. Que se marque depende de tu grasa corporal: por eso el programa ajusta tu comida y tus pasos.","outcomes":["4 sesiones de unos 40 minutos por semana","Abdomen al frente, oblicuos, abdomen inferior y core profundo","Calorías y proteína del programa si tienes Entreno + Nutrición","Medida de cintura y foto comparadas con el día 1"],"keyLifts":["plank","rdl","goblet"],"nutrition":{"mode":"acelerada","proteinPerKg":2,"note":"Déficit moderado y proteína alta: el abdomen se marca cuando baja la grasa, sin perder músculo."},"previewExercise":"plank","experience":{"mode":"Modo abdomen","welcome":"Empieza Abdomen marcado. Tu core se entrena en cada sesión, pero lo que lo deja ver es bajar la grasa: pasos, agua y comida cuentan igual que los ejercicios.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"pasos","label":"Camina 10.000 pasos","kind":"pasos","target":10000},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sin-azucar","label":"Cero bebidas azucaradas hoy","kind":"check"}],"tips":["Semana 1: mide tu cintura a la altura del ombligo, en ayunas. Es tu número del día 1.","Semana 2: en el dead bug, la espalda baja no se despega del piso. Si se despega, acorta el movimiento.","Semana 3: las bebidas azucaradas son las calorías más fáciles de quitar. Cámbialas por agua o café sin azúcar.","Semana 4: en el crunch con polea, piensa en llevar las costillas hacia la cadera, no la cabeza hacia las rodillas.","Semana 5: si la báscula no se mueve, mira la cinta métrica. La cintura suele bajar primero.","Semana 6: semana pico. Mide tu cintura y toma tu foto el último día para compararla con el día 1."],"coachFocus":"Abdomen más marcado: core fuerte (anti-extensión, oblicuos, abdomen inferior) y bajar grasa con déficit moderado, proteína alta y pasos.","restDay":"Descanso activo: camina 30 minutos y 2 minutos de plancha","food":["Déficit moderado y constante: el abdomen se marca cuando baja la grasa de todo el cuerpo.","Proteína alta en cada comida para no perder músculo mientras bajas.","Llena medio plato de verduras y suma frijoles o avena: la fibra calma el hambre.","Recorta primero lo líquido: refrescos, jugos y alcohol."]}}$j$::jsonb)
insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('brazos-definidos', 'Brazos definidos', '6 semanas de especialización en brazos: bíceps, tríceps y hombros en cada sesión, con curl inclinado y tríceps sobre la cabeza para trabajar el músculo estirado. 3 sesiones y 1 de bombeo opcional por semana.', 42, '{}'::jsonb, 'publicado', 6.99, 'media', 45, 'ember', 'barbell', 'workout', 0, 350, 'Brazos definidos', 'Brazos de acero', 'libre', false, false, 'Si sientes dolor en el codo o el hombro (no cansancio muscular), baja el peso y consulta con un profesional antes de seguir.', 30, 'programa', $j${"phases":[{"name":"Base","weeks":2,"focus":"Técnica estricta en curl, tríceps y press. Codos quietos, bajadas lentas."},{"name":"Volumen","weeks":3,"focus":"Una serie más en los principales. Cuando llegas al tope del rango, sube el peso."},{"name":"Pico","weeks":1,"focus":"Más carga en los básicos y la foto de tus brazos del último día."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio (se adapta a casa con mancuernas)","adapt":true,"who":"Para quien quiere brazos firmes y definidos: bíceps, tríceps y hombros como prioridad durante 6 semanas.","result":"Construir bíceps, tríceps y hombros con 3 sesiones de brazos por semana y una de bombeo opcional, con ejercicios en posición estirada y pesos que suben solos. Mantén tus pasos para cuidar las piernas.","outcomes":["Unas 14 a 18 series semanales de bíceps y de tríceps","Hombro lateral y posterior para un brazo que se ve más ancho","Sesión opcional de bombeo de 20 minutos","Fuerza en curl y press cerrado comparada con el día 1"],"keyLifts":["curl","closebench","dbpress"],"nutrition":{"mode":"recomp","proteinPerKg":1.8,"note":"Déficit pequeño y proteína alta: ganas músculo en los brazos mientras se ve más la definición."},"previewExercise":"curl","experience":{"mode":"Modo brazos","welcome":"Empieza Brazos definidos. Codos quietos, bajadas lentas y pesos que suben solos: así se construyen brazos firmes.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"hombros","label":"2 minutos de movilidad de hombros","kind":"check"}],"tips":["Semana 1: en el curl, los codos no se mueven. Si tienes que balancearte, el peso es demasiado alto.","Semana 2: el tríceps es dos tercios de tu brazo. Estira del todo en cada extensión.","Semana 3: el hombro lateral hace que el brazo se vea más ancho. Sube hasta la altura del hombro, sin impulso.","Semana 4: en el curl inclinado y la extensión sobre la cabeza, la bajada lenta y el estiramiento completo son lo que más hace crecer el brazo.","Semana 5: la sesión de bombeo es opcional. Si te sobra energía, súmala; si no, descansa.","Semana 6: semana pico. Toma tu foto con la misma luz que el día 1 y compara."],"coachFocus":"Brazos definidos: bíceps, tríceps y hombros con técnica estricta y sobrecarga progresiva, sin descuidar pierna y espalda.","restDay":"Descanso activo: camina 20 minutos y estira hombros y pecho","food":["Proteína en cada comida: el brazo crece con ladrillos.","Déficit pequeño: si recortas mucho, el brazo no crece.","Carbohidrato antes de entrenar para rendir en las series de brazos.","Hidrátate bien: el músculo lleno de agua y glucógeno se ve más firme."]}}$j$::jsonb)
insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('banana-girl', 'Banana Girl', '6 semanas para chicas: glúteos firmes, cintura definida, brazos tonificados y mejor postura, con cardio suave sin saltos y hábitos de autocuidado cada día.', 42, '{}'::jsonb, 'publicado', 7.99, 'facil', 45, 'fresa', 'sparkle', 'workout', 0, 400, 'Banana Girl', 'Glow up', 'libre', true, false, 'Si estás embarazada, tuviste un parto reciente o tienes una condición médica, consulta con tu médico antes de empezar.', 15, 'programa', $j${"phases":[{"name":"Aprende y activa","weeks":2,"focus":"Siente el glúteo, cuida la postura y aprende cada movimiento sin prisa."},{"name":"Tonifica","weeks":3,"focus":"Más series y más peso en glúteo y brazos. Tu cuerpo se pone firme."},{"name":"Brilla","weeks":1,"focus":"Tus pesos más altos y la comparación con tu día 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"principiante","equipment":"Gimnasio o casa con mancuernas","adapt":true,"who":"Para chicas que quieren glúteos más firmes, cintura definida, brazos tonificados y mejor postura, con un plan claro y amable desde el primer día.","result":"Tonificar todo el cuerpo con prioridad en glúteo: 2 sesiones de glúteo y pierna, 1 de brazos y postura y 1 de cintura y cardio suave por semana.","outcomes":["4 sesiones de unos 45 minutos por semana","Glúteo en 3 de las 4 sesiones","Brazos y espalda para una postura erguida","Cardio suave sin saltos y hábitos de autocuidado cada día"],"keyLifts":["ds:1409","goblet","rdl"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Déficit pequeño y proteína suficiente: tonificas sin pasar hambre."},"previewExercise":"rdl","experience":{"mode":"Modo Banana Girl","welcome":"Bienvenida a Banana Girl. Seis semanas para sentirte firme y fuerte, a tu ritmo. Hoy empieza tu glow up.","habits":[{"key":"entreno","label":"Sesión del programa","kind":"entreno"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"pasos","label":"Camina 8.000 pasos","kind":"pasos","target":8000},{"key":"autocuidado","label":"10 minutos para ti: estira o respira","kind":"check"}],"tips":["Semana 1: antes de cada sesión de glúteo, haz 2 series de puente sin peso. Vas a sentirlo mucho más.","Semana 2: hombros atrás y abajo, también fuera del gym. La postura cambia cómo te ves desde el primer día.","Semana 3: no tengas miedo a subir el peso. Las cargas te tonifican; no te van a hacer ver voluminosa de un día para otro.","Semana 4: tu ciclo puede cambiar tu energía. Si un día te sientes baja, repite el peso de la vez pasada y listo.","Semana 5: la proteína también es para ti. Súmala en el desayuno: huevos, yogur griego o queso.","Semana 6: semana para brillar. Toma tus medidas y tu foto el último día y mira todo lo que lograste."],"coachFocus":"Tonificar el cuerpo de una chica con prioridad en glúteo, cintura, brazos y postura. Tono cálido y motivador, sin presión por el peso.","restDay":"Descanso activo: 20 minutos de caminata y 10 de estiramiento","food":["Proteína en cada comida, empezando por el desayuno: huevos, yogur griego o queso.","Déficit pequeño: tonificas sin pasar hambre ni perder energía.","Hierro y calcio cuentan: frijoles, hojas verdes, lácteos y carnes magras.","Antes de entrenar, una fruta o un pan con algo de proteína."]}}$j$::jsonb)
